import express from "express";
import path from "path";
import { createServer as createViteServer } from "vite";

async function startServer() {
  const app = express();
  const PORT = 3000;

  // 1. Define custom assetlinks array with the app packages and SHA-256 fingerprint
  const assetlinks = [
    {
      relation: ["delegate_permission/common.handle_all_urls"],
      target: {
        namespace: "android_app",
        package_name: "in.newtons.payroll.twa",
        sha256_cert_fingerprints: [
          "BE:4A:1A:8B:C6:05:6F:57:D5:C1:44:FD:7D:E2:22:17:CB:13:9C:F2:72:F6:CF:5B:55:FD:9B:DA:42:C5:B1:02"
        ]
      }
    },
    {
      relation: ["delegate_permission/common.handle_all_urls"],
      target: {
        namespace: "android_app",
        package_name: "com.newtons.payroll",
        sha256_cert_fingerprints: [
          "BE:4A:1A:8B:C6:05:6F:57:D5:C1:44:FD:7D:E2:22:17:CB:13:9C:F2:72:F6:CF:5B:55:FD:9B:DA:42:C5:B1:02"
        ]
      }
    }
  ];

  // 2. Serve the assetlinks endpoint explicitly with correct Content-Type header
  app.get("/.well-known/assetlinks.json", (req, res) => {
    res.setHeader("Content-Type", "application/json");
    res.json(assetlinks);
  });

  // Health check endpoint
  app.get("/api/health", (req, res) => {
    res.json({ status: "ok" });
  });

  // 3. Mount Vite middleware for dev or Serve compiled client bundle in production
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://localhost:${PORT}`);
  });
}

startServer();
